const iasgs = [];

push(iasgs, 'IAS-GS', 'History of India', 'Ancient India', [
  { q: 'The Indus Valley Civilization was primarily:', a: 'Rural and pastoral', b: 'Urban and well-planned', c: 'Nomadic', d: 'Forest-based', ans: 'B', sol: 'The Indus Valley (Harappan) Civilization was notable for its advanced urban planning, including grid-pattern streets, drainage systems, and standardized brick sizes.', diff: 'Easy' },
  { q: 'The Ashoka Pillar at Sarnath is associated with:', a: 'Buddha\'s birth', b: 'Buddha\'s first sermon', c: 'Buddha\'s death', d: 'Buddha\'s enlightenment', ans: 'B', sol: 'Sarnath is where Buddha delivered his first sermon (Dhammacakkappavattana Sutta). The Ashoka Pillar with its lion capital was erected here to commemorate this event.', diff: 'Easy' },
  { q: 'Which Vedic text is considered the oldest?', a: 'Sama Veda', b: 'Yajur Veda', c: 'Rig Veda', d: 'Atharva Veda', ans: 'C', sol: 'The Rig Veda (c. 1500-1200 BCE) is the oldest of the four Vedas and one of the oldest known texts in any Indo-European language.', diff: 'Easy' },
  { q: 'The Mauryan Empire was founded by:', a: 'Ashoka', b: 'Bindusara', c: 'Chandragupta Maurya', d: 'Chanakya', ans: 'C', sol: 'Chandragupta Maurya founded the Mauryan Empire around 321 BCE with the guidance of his advisor Chanakya (Kautilya). Ashoka was his grandson.', diff: 'Easy' },
  { q: 'The concept of "Dharma Chakra" on the Indian national flag is taken from:', a: 'Ajanta Caves', b: 'Sarnath Lion Capital', c: 'Sanchi Stupa', d: 'Ellora Caves', ans: 'B', sol: 'The 24-spoke Dharma Chakra (Wheel of Law) on India\'s flag is derived from the Ashoka Pillar at Sarnath, which also provides the national emblem.', diff: 'Easy' },
  { q: 'Nalanda University was destroyed by:', a: 'Mahmud of Ghazni', b: 'Bakhtiyar Khilji', c: 'Muhammad Ghori', d: 'Timur', ans: 'B', sol: 'Bakhtiyar Khilji destroyed Nalanda University around 1193 CE. The library was so vast that it reportedly burned for three months.', diff: 'Medium' },
]);

push(iasgs, 'IAS-GS', 'History of India', 'Modern India', [
  { q: 'The Permanent Settlement of 1793 was introduced by:', a: 'Lord Cornwallis', b: 'Lord Wellesley', c: 'Lord Dalhousie', d: 'Lord Curzon', ans: 'A', sol: 'Lord Cornwallis introduced the Permanent Settlement in Bengal in 1793, fixing land revenue to be paid by zamindars to the British government permanently.', diff: 'Easy' },
  { q: 'The Doctrine of Lapse was associated with:', a: 'Lord Canning', b: 'Lord Dalhousie', c: 'Lord Bentinck', d: 'Lord Ripon', ans: 'B', sol: 'Lord Dalhousie used the Doctrine of Lapse to annex Indian states whose rulers died without natural heirs, including Satara, Jhansi, and Nagpur.', diff: 'Easy' },
]);

push(iasgs, 'IAS-GS', 'Indian National Movement', 'Gandhian Era', [
  { q: 'The Non-Cooperation Movement was launched in:', a: '1919', b: '1920', c: '1930', d: '1942', ans: 'B', sol: 'Gandhi launched the Non-Cooperation Movement in 1920 against the Rowlatt Act and Jallianwala Bagh massacre. It was suspended in 1922 after the Chauri Chaura incident.', diff: 'Easy' },
  { q: 'The Salt March (Dandi March) took place in:', a: '1928', b: '1930', c: '1932', d: '1942', ans: 'B', sol: 'Gandhi led the Salt March from Sabarmati Ashram to Dandi (about 390 km) in March-April 1930 to protest the British salt tax, launching the Civil Disobedience Movement.', diff: 'Easy' },
  { q: '"Do or Die" was the slogan of which movement?', a: 'Non-Cooperation Movement', b: 'Civil Disobedience Movement', c: 'Quit India Movement', d: 'Swadeshi Movement', ans: 'C', sol: 'Gandhi gave the "Do or Die" (Karo ya Maro) call during the Quit India Movement launched on August 8, 1942, demanding an end to British rule.', diff: 'Easy' },
  { q: 'The Jallianwala Bagh massacre occurred in:', a: '1917', b: '1919', c: '1921', d: '1930', ans: 'B', sol: 'On April 13, 1919, General Dyer ordered troops to fire on a peaceful gathering at Jallianwala Bagh in Amritsar, killing hundreds of unarmed civilians.', diff: 'Easy' },
  { q: 'Who founded the Indian National Congress in 1885?', a: 'Dadabhai Naoroji', b: 'A.O. Hume', c: 'Bal Gangadhar Tilak', d: 'Gopal Krishna Gokhale', ans: 'B', sol: 'Allan Octavian Hume, a retired British civil servant, founded the Indian National Congress in 1885. The first session was held in Bombay under W.C. Bonnerjee.', diff: 'Easy' },
  { q: 'The Rowlatt Act of 1919 was opposed because it:', a: 'Increased taxes', b: 'Allowed detention without trial', c: 'Banned Indian languages', d: 'Closed Indian schools', ans: 'B', sol: 'The Rowlatt Act allowed the British government to imprison any person suspected of terrorism without trial for up to two years, severely curtailing civil liberties.', diff: 'Easy' },
]);

push(iasgs, 'IAS-GS', 'Indian and World Geography', 'Physical Geography', [
  { q: 'The Tropic of Cancer passes through how many Indian states?', a: '6', b: '7', c: '8', d: '9', ans: 'C', sol: 'The Tropic of Cancer (23.5°N) passes through 8 Indian states: Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura, and Mizoram.', diff: 'Medium' },
  { q: 'Which is the longest river in India?', a: 'Godavari', b: 'Ganga', c: 'Brahmaputra', d: 'Krishna', ans: 'B', sol: 'The Ganga is the longest river in India at approximately 2,525 km. Godavari (1,465 km) is the longest peninsular river.', diff: 'Easy' },
  { q: 'The Western Ghats are also known as:', a: 'Sahyadri', b: 'Vindhya', c: 'Satpura', d: 'Aravalli', ans: 'A', sol: 'The Western Ghats are also called Sahyadri. They run along the western coast of India for about 1,600 km from Gujarat to Tamil Nadu.', diff: 'Easy' },
  { q: 'Which Indian state has the longest coastline?', a: 'Tamil Nadu', b: 'Andhra Pradesh', c: 'Gujarat', d: 'Maharashtra', ans: 'C', sol: 'Gujarat has the longest coastline among Indian states at approximately 1,600 km, followed by Andhra Pradesh and Tamil Nadu.', diff: 'Easy' },
  { q: 'The Deccan Plateau is bounded by:', a: 'Western Ghats only', b: 'Eastern Ghats only', c: 'Western Ghats, Eastern Ghats, and Satpura Range', d: 'Himalayas and Vindhyas', ans: 'C', sol: 'The Deccan Plateau is a triangular landmass bounded by the Western Ghats (west), Eastern Ghats (east), and the Satpura-Vindhya ranges (north).', diff: 'Medium' },
  { q: 'Monsoon winds in India are caused primarily by:', a: 'Rotation of the Earth', b: 'Differential heating of land and sea', c: 'Gravitational pull of the Moon', d: 'Volcanic activity', ans: 'B', sol: 'The Indian monsoon is driven by differential heating between the Indian landmass and the Indian Ocean, creating pressure differences that drive seasonal wind patterns.', diff: 'Easy' },
]);

push(iasgs, 'IAS-GS', 'Indian and World Geography', 'Indian Geography', [
  { q: 'The Chilika Lake is located in:', a: 'Kerala', b: 'Odisha', c: 'Tamil Nadu', d: 'Andhra Pradesh', ans: 'B', sol: 'Chilika Lake in Odisha is the largest coastal lagoon in India and the second largest in the world. It is a Ramsar wetland site.', diff: 'Easy' },
  { q: 'Which soil type is most suitable for cotton cultivation?', a: 'Alluvial soil', b: 'Black soil (Regur)', c: 'Red soil', d: 'Laterite soil', ans: 'B', sol: 'Black soil (Regur/Black Cotton Soil) is ideal for cotton cultivation due to its high moisture retention capacity. It is found mainly in the Deccan Plateau.', diff: 'Easy' },
]);

push(iasgs, 'IAS-GS', 'Indian Polity and Governance', 'Constitution', [
  { q: 'The Indian Constitution was adopted on:', a: 'January 26, 1950', b: 'November 26, 1949', c: 'August 15, 1947', d: 'January 26, 1949', ans: 'B', sol: 'The Constitution was adopted on November 26, 1949, and came into effect on January 26, 1950 (Republic Day). August 15, 1947 was Independence Day.', diff: 'Easy' },
  { q: 'The Preamble of the Indian Constitution begins with:', a: '"We, the citizens of India"', b: '"We, the people of India"', c: '"We, the representatives of India"', d: '"We, the government of India"', ans: 'B', sol: '"We, the people of India" — this phrase establishes popular sovereignty, meaning the Constitution derives its authority from the people of India.', diff: 'Easy' },
  { q: 'Which article abolishes untouchability?', a: 'Article 14', b: 'Article 15', c: 'Article 17', d: 'Article 21', ans: 'C', sol: 'Article 17 abolishes untouchability and forbids its practice in any form. Enforcement of any disability arising from untouchability is a punishable offence.', diff: 'Easy' },
  { q: 'The concept of Fundamental Duties was added by which amendment?', a: '42nd Amendment', b: '44th Amendment', c: '73rd Amendment', d: '86th Amendment', ans: 'A', sol: 'The 42nd Amendment (1976) added Fundamental Duties under Article 51A, based on the Swaran Singh Committee recommendations. Originally 10 duties, now 11.', diff: 'Medium' },
  { q: 'Right to Education is a Fundamental Right under:', a: 'Article 19', b: 'Article 21', c: 'Article 21A', d: 'Article 45', ans: 'C', sol: 'Article 21A (added by 86th Amendment, 2002) makes free and compulsory education a Fundamental Right for children aged 6-14 years.', diff: 'Medium' },
  { q: 'The President of India is elected by:', a: 'Direct election by citizens', b: 'Members of Parliament only', c: 'An electoral college of elected MPs and MLAs', d: 'The Prime Minister', ans: 'C', sol: 'The President is elected by an electoral college consisting of elected members of both Houses of Parliament and elected members of State Legislative Assemblies (Article 54).', diff: 'Easy' },
]);

push(iasgs, 'IAS-GS', 'Indian Polity and Governance', 'Fundamental Rights', [
  { q: 'Which Fundamental Right is available only to Indian citizens and not to foreigners?', a: 'Right to Equality (Art. 14)', b: 'Right to Freedom of Speech (Art. 19)', c: 'Right to Life (Art. 21)', d: 'Right against Exploitation (Art. 23)', ans: 'B', sol: 'Article 19 rights (speech, assembly, movement, etc.) are available only to citizens. Articles 14, 21, and 23 are available to all persons including foreigners.', diff: 'Medium' },
  { q: 'The Right to Property was removed as a Fundamental Right by:', a: '42nd Amendment', b: '44th Amendment', c: '73rd Amendment', d: '86th Amendment', ans: 'B', sol: 'The 44th Amendment (1978) removed Right to Property from Fundamental Rights. It is now a legal right under Article 300A.', diff: 'Easy' },
]);

push(iasgs, 'IAS-GS', 'Economic and Social Development', 'Indian Economy', [
  { q: 'India\'s GDP is primarily driven by which sector?', a: 'Agriculture', b: 'Industry', c: 'Services', d: 'Mining', ans: 'C', sol: 'The services sector contributes approximately 54% of India\'s GDP, followed by industry (~26%) and agriculture (~20%).', diff: 'Easy' },
  { q: 'The Reserve Bank of India was established in:', a: '1935', b: '1947', c: '1950', d: '1969', ans: 'A', sol: 'RBI was established on April 1, 1935, based on the recommendations of the Hilton Young Commission. It was nationalized in 1949.', diff: 'Easy' },
  { q: 'NITI Aayog replaced which body?', a: 'Finance Commission', b: 'Planning Commission', c: 'Election Commission', d: 'Law Commission', ans: 'B', sol: 'NITI Aayog (National Institution for Transforming India) replaced the Planning Commission on January 1, 2015, shifting from centralized planning to cooperative federalism.', diff: 'Easy' },
  { q: 'GST was implemented in India from:', a: 'April 1, 2016', b: 'July 1, 2017', c: 'January 1, 2018', d: 'April 1, 2017', ans: 'B', sol: 'The Goods and Services Tax (GST) was launched on July 1, 2017, through the 101st Constitutional Amendment, replacing multiple indirect taxes.', diff: 'Easy' },
  { q: 'The fiscal deficit of the government refers to:', a: 'Total expenditure minus total revenue', b: 'Total borrowing minus interest payments', c: 'Total expenditure minus total receipts excluding borrowings', d: 'Revenue expenditure minus revenue receipts', ans: 'C', sol: 'Fiscal Deficit = Total Expenditure - Total Receipts (excluding borrowings). It indicates the total borrowing requirement of the government.', diff: 'Medium' },
  { q: 'Which of the following is NOT a direct tax?', a: 'Income Tax', b: 'Corporate Tax', c: 'GST', d: 'Capital Gains Tax', ans: 'C', sol: 'GST is an indirect tax levied on goods and services. Direct taxes (Income Tax, Corporate Tax, Capital Gains Tax) are paid directly by the taxpayer to the government.', diff: 'Easy' },
]);

push(iasgs, 'IAS-GS', 'Economic and Social Development', 'Government Schemes', [
  { q: 'The Mahatma Gandhi National Rural Employment Guarantee Act (MGNREGA) guarantees:', a: '50 days of employment', b: '100 days of employment', c: '150 days of employment', d: '200 days of employment', ans: 'B', sol: 'MGNREGA guarantees 100 days of wage employment per year to every rural household whose adult members volunteer to do unskilled manual work.', diff: 'Easy' },
  { q: 'The Pradhan Mantri Jan Dhan Yojana aims at:', a: 'Free healthcare', b: 'Financial inclusion', c: 'Free education', d: 'Housing for all', ans: 'B', sol: 'PMJDY (launched 2014) is a financial inclusion program providing universal access to banking facilities with zero-balance accounts, RuPay debit cards, and insurance cover.', diff: 'Easy' },
]);

push(iasgs, 'IAS-GS', 'Environmental Ecology', 'Ecology', [
  { q: 'Which of the following is a biodiversity hotspot in India?', a: 'Thar Desert', b: 'Western Ghats', c: 'Indo-Gangetic Plain', d: 'Deccan Plateau', ans: 'B', sol: 'India has 4 biodiversity hotspots: Western Ghats, Eastern Himalayas, Indo-Burma, and Sundaland. The Western Ghats host over 5,000 flowering plant species.', diff: 'Easy' },
  { q: 'The Kyoto Protocol is related to:', a: 'Biodiversity conservation', b: 'Greenhouse gas emission reduction', c: 'Ozone layer protection', d: 'Marine pollution', ans: 'B', sol: 'The Kyoto Protocol (1997) is an international treaty committing industrialized nations to reduce greenhouse gas emissions. It was the first binding agreement on climate change.', diff: 'Easy' },
  { q: 'The National Action Plan on Climate Change (NAPCC) includes how many missions?', a: '6', b: '8', c: '10', d: '12', ans: 'B', sol: 'NAPCC (2008) includes 8 missions: Solar, Enhanced Energy Efficiency, Sustainable Habitat, Water, Sustaining Himalayan Ecosystem, Green India, Sustainable Agriculture, and Strategic Knowledge.', diff: 'Medium' },
  { q: 'Coral reefs are formed by:', a: 'Volcanic activity', b: 'Marine organisms (polyps)', c: 'Tidal waves', d: 'Glacial deposits', ans: 'B', sol: 'Coral reefs are built by colonies of tiny animals called coral polyps, which secrete calcium carbonate to form hard skeletons. They thrive in warm, shallow, clear waters.', diff: 'Easy' },
  { q: 'The Ramsar Convention is related to:', a: 'Wetland conservation', b: 'Forest protection', c: 'Air pollution', d: 'Wildlife trade', ans: 'A', sol: 'The Ramsar Convention (1971) is an international treaty for the conservation and sustainable use of wetlands. India has over 75 Ramsar sites.', diff: 'Easy' },
  { q: 'Which gas is the largest contributor to the greenhouse effect?', a: 'Carbon dioxide', b: 'Methane', c: 'Water vapor', d: 'Nitrous oxide', ans: 'C', sol: 'Water vapor is the most abundant greenhouse gas and contributes most to the natural greenhouse effect. However, CO2 is the most significant human-caused greenhouse gas.', diff: 'Hard' },
]);

push(iasgs, 'IAS-GS', 'Environmental Ecology', 'Conservation', [
  { q: 'Project Tiger was launched in:', a: '1970', b: '1972', c: '1973', d: '1975', ans: 'C', sol: 'Project Tiger was launched on April 1, 1973, to protect the Bengal tiger. Jim Corbett National Park was the first tiger reserve. India now has 50+ tiger reserves.', diff: 'Easy' },
  { q: 'The Wildlife Protection Act was enacted in:', a: '1970', b: '1972', c: '1986', d: '1991', ans: 'B', sol: 'The Wildlife Protection Act, 1972, provides for the protection of wild animals, birds, and plants. It established the framework for wildlife sanctuaries and national parks.', diff: 'Easy' },
]);

push(iasgs, 'IAS-GS', 'General Science', 'Physics', [
  { q: 'The SI unit of force is:', a: 'Joule', b: 'Newton', c: 'Watt', d: 'Pascal', ans: 'B', sol: 'The Newton (N) is the SI unit of force. 1 Newton = force needed to accelerate 1 kg mass by 1 m/s². Named after Sir Isaac Newton.', diff: 'Easy' },
  { q: 'Which phenomenon explains why the sky appears blue?', a: 'Reflection', b: 'Refraction', c: 'Rayleigh scattering', d: 'Diffraction', ans: 'C', sol: 'Rayleigh scattering causes shorter wavelengths (blue/violet) to scatter more than longer wavelengths. Our eyes are more sensitive to blue, making the sky appear blue.', diff: 'Easy' },
  { q: 'A concave mirror is used in:', a: 'Rear-view mirrors', b: 'Headlights of cars', c: 'Periscopes', d: 'Kaleidoscopes', ans: 'B', sol: 'Concave mirrors converge light and are used in headlights, searchlights, and solar concentrators. Convex mirrors (diverging) are used in rear-view mirrors.', diff: 'Easy' },
]);

push(iasgs, 'IAS-GS', 'General Science', 'Biology', [
  { q: 'DNA stands for:', a: 'Di-Nucleic Acid', b: 'Deoxyribonucleic Acid', c: 'Deoxy-Nucleotide Acid', d: 'Di-Nitrogen Acid', ans: 'B', sol: 'DNA (Deoxyribonucleic Acid) is the molecule that carries genetic instructions for development, functioning, growth, and reproduction of all known organisms.', diff: 'Easy' },
  { q: 'Photosynthesis primarily occurs in:', a: 'Roots', b: 'Stems', c: 'Leaves', d: 'Flowers', ans: 'C', sol: 'Photosynthesis primarily occurs in leaves, specifically in chloroplasts containing chlorophyll. The process converts CO2 and water into glucose and oxygen using sunlight.', diff: 'Easy' },
  { q: 'Which vitamin deficiency causes scurvy?', a: 'Vitamin A', b: 'Vitamin B12', c: 'Vitamin C', d: 'Vitamin D', ans: 'C', sol: 'Scurvy is caused by Vitamin C (ascorbic acid) deficiency. Symptoms include bleeding gums, weakness, and poor wound healing. Found in citrus fruits and vegetables.', diff: 'Easy' },
]);

push(iasgs, 'IAS-GS', 'General Science', 'Chemistry', [
  { q: 'The pH of pure water is:', a: '0', b: '7', c: '14', d: '1', ans: 'B', sol: 'Pure water has a pH of 7, which is neutral. pH < 7 is acidic, pH > 7 is basic/alkaline. The pH scale ranges from 0 to 14.', diff: 'Easy' },
  { q: 'Which gas is used in fire extinguishers?', a: 'Oxygen', b: 'Nitrogen', c: 'Carbon dioxide', d: 'Hydrogen', ans: 'C', sol: 'CO2 is used in fire extinguishers because it is heavier than air, does not support combustion, and smothers the fire by displacing oxygen.', diff: 'Easy' },
]);

push(iasgs, 'IAS-GS', 'Current Events', 'National Affairs', [
  { q: 'The G20 presidency was held by India in:', a: '2022', b: '2023', c: '2024', d: '2025', ans: 'B', sol: 'India held the G20 presidency from December 1, 2022 to November 30, 2023, with the theme "One Earth, One Family, One Future." The summit was held in New Delhi.', diff: 'Easy' },
  { q: 'The Chandrayaan-3 mission successfully landed on the Moon in:', a: 'July 2023', b: 'August 2023', c: 'September 2023', d: 'October 2023', ans: 'B', sol: 'Chandrayaan-3 successfully soft-landed on the Moon\'s south pole on August 23, 2023, making India the fourth country to land on the Moon and the first to land near the south pole.', diff: 'Easy' },
  { q: 'The Aditya-L1 mission is related to:', a: 'Mars exploration', b: 'Solar observation', c: 'Lunar mapping', d: 'Asteroid mining', ans: 'B', sol: 'Aditya-L1 is India\'s first space-based solar observatory, launched in September 2023. It studies the Sun from the Lagrange point 1 (L1), about 1.5 million km from Earth.', diff: 'Easy' },
  { q: 'The Uniform Civil Code debate in India relates to:', a: 'Uniform tax laws', b: 'Common personal laws for all citizens', c: 'Uniform education policy', d: 'Common criminal laws', ans: 'B', sol: 'The Uniform Civil Code (Article 44, Directive Principles) envisions common personal laws (marriage, divorce, inheritance) for all citizens regardless of religion.', diff: 'Easy' },
  { q: 'Digital India initiative was launched in:', a: '2014', b: '2015', c: '2016', d: '2017', ans: 'B', sol: 'Digital India was launched on July 1, 2015, to transform India into a digitally empowered society with focus on digital infrastructure, governance, and digital literacy.', diff: 'Easy' },
  { q: 'The Swachh Bharat Mission was launched on:', a: 'August 15, 2014', b: 'October 2, 2014', c: 'January 26, 2015', d: 'November 19, 2014', ans: 'B', sol: 'Swachh Bharat Mission was launched on October 2, 2014 (Gandhi Jayanti) to achieve universal sanitation coverage and eliminate open defecation by 2019.', diff: 'Easy' },
]);

// ============================================================
// 3. IAS-CSAT — 80 questions (subject: Aptitude)
// ============================================================
const iascsat = [];

push(iascsat, 'IAS-CSAT', 'Aptitude', 'Comprehension', [
  { q: '"The true test of civilization is not the census, nor the size of cities, but the kind of man the country turns out." This means:', a: 'Population determines civilization', b: 'City size reflects progress', c: 'The quality of citizens defines civilization', d: 'Census data is unreliable', ans: 'C', sol: 'Emerson\'s quote argues that civilization should be measured by the character and quality of its people, not by quantitative metrics like population or urbanization.', diff: 'Easy' },
  { q: 'A passage states: "Artificial Intelligence will not replace humans, but humans who use AI will replace those who don\'t." The key message is:', a: 'AI is dangerous', b: 'Adapting to AI is essential for relevance', c: 'AI will replace all jobs', d: 'Humans are superior to AI', ans: 'B', sol: 'The statement emphasizes that AI is a tool — those who learn to use it will have an advantage over those who resist it. Adaptability is the key message.', diff: 'Medium' },
  { q: '"Justice delayed is justice denied." This principle implies:', a: 'Courts should rush judgments', b: 'Timely justice is essential for it to be meaningful', c: 'Justice is impossible', d: 'Delays are always intentional', ans: 'B', sol: 'This legal maxim (attributed to Gladstone) means that if justice is not delivered in a timely manner, it effectively amounts to injustice, as the aggrieved party suffers prolonged harm.', diff: 'Easy' },
  { q: 'An author argues: "Economic growth without environmental sustainability is like building a house on sand." The analogy suggests:', a: 'Houses should not be built on sand', b: 'Unsustainable growth will eventually collapse', c: 'Economics and environment are unrelated', d: 'Sand is a poor building material', ans: 'B', sol: 'The biblical allusion (house on sand) warns that growth built without a sustainable foundation (environmental care) is fragile and will eventually fail.', diff: 'Easy' },
  { q: '"The best argument against democracy is a five-minute conversation with the average voter." This quote by Churchill is:', a: 'A defense of democracy', b: 'A criticism of voter ignorance', c: 'An argument for monarchy', d: 'A praise of voters', ans: 'B', sol: 'Churchill\'s witty remark highlights the paradox of democracy — it depends on informed citizens, yet many voters may lack sufficient knowledge. It\'s a critique, not a rejection of democracy.', diff: 'Medium' },
  { q: 'A passage discusses how traditional knowledge systems complement modern science. The author\'s stance is:', a: 'Traditional knowledge is superior', b: 'Modern science should be abandoned', c: 'Both systems have value and can work together', d: 'Traditional knowledge is outdated', ans: 'C', sol: 'The word "complement" indicates the author sees both systems as having unique strengths that can enhance each other, rather than one being superior.', diff: 'Easy' },
  { q: '"Power tends to corrupt, and absolute power corrupts absolutely." Lord Acton\'s statement argues for:', a: 'Concentration of power', b: 'Checks and balances on power', c: 'Abolition of government', d: 'Military rule', ans: 'B', sol: 'Acton\'s famous quote is an argument for limiting power through checks and balances, separation of powers, and accountability mechanisms to prevent corruption.', diff: 'Easy' },
  { q: 'A report states: "India\'s demographic dividend can become a demographic disaster if not accompanied by skill development." This means:', a: 'India has too many people', b: 'Young population is an asset only if properly skilled', c: 'Skill development is unnecessary', d: 'Demographics don\'t matter', ans: 'B', sol: 'A large young population (demographic dividend) is beneficial only if these people are educated and skilled. Without investment in human capital, it becomes a burden.', diff: 'Easy' },
  { q: '"Those who cannot remember the past are condemned to repeat it." Santayana\'s quote emphasizes:', a: 'History is boring', b: 'The importance of learning from history', c: 'The past should be forgotten', d: 'Repetition is good', ans: 'B', sol: 'This famous quote argues that understanding historical mistakes and patterns is essential to avoid repeating them. It underscores the practical value of historical knowledge.', diff: 'Easy' },
  { q: 'An editorial argues that social media has democratized information but also created echo chambers. The central paradox is:', a: 'Social media is entirely good', b: 'More access to information can lead to less diverse viewpoints', c: 'Echo chambers don\'t exist', d: 'Democracy requires social media', ans: 'B', sol: 'The paradox: while social media gives everyone access to information (democratization), algorithms tend to show users content they already agree with, narrowing perspectives (echo chambers).', diff: 'Medium' },
]);

push(iascsat, 'IAS-CSAT', 'Aptitude', 'Logical Reasoning', [
  { q: 'All politicians are public speakers. Some public speakers are writers. Which conclusion follows?', a: 'All politicians are writers', b: 'Some politicians may be writers', c: 'No politicians are writers', d: 'All writers are politicians', ans: 'B', sol: 'Since all politicians are public speakers, and some public speakers are writers, it is possible (but not certain) that some politicians are writers.', diff: 'Medium' },
  { q: 'If FRIEND is coded as HUMGPF, then CANDLE is coded as:', a: 'ECPFNG', b: 'EDRFNI', c: 'ECPFNH', d: 'ECPFME', ans: 'A', sol: 'Each letter is shifted by +2: F→H, R→U... Wait, F(6)→H(8), R(18)→U(21)? Let me recheck: F+2=H, R+2=T... The pattern is each letter +2: C+2=E, A+2=C, N+2=P, D+2=F, L+2=N, E+2=G. Answer: ECPFNG.', diff: 'Easy' },
  { q: 'Statement: "Some teachers are researchers. All researchers are scholars." Conclusion: "Some teachers are scholars."', a: 'Definitely true', b: 'Probably true', c: 'Cannot be determined', d: 'False', ans: 'A', sol: 'Some teachers are researchers, and ALL researchers are scholars. Therefore, those teachers who are researchers must also be scholars. "Some teachers are scholars" definitely follows.', diff: 'Easy' },
  { q: 'P is taller than Q. R is shorter than Q. S is taller than P. Who is the shortest?', a: 'P', b: 'Q', c: 'R', d: 'S', ans: 'C', sol: 'Order: S > P > Q > R. R is the shortest.', diff: 'Easy' },
  { q: 'Find the odd one out: 2, 5, 10, 17, 28, 37', a: '28', b: '37', c: '17', d: '10', ans: 'A', sol: 'Pattern: differences should be 3, 5, 7, 9, 11 (odd numbers). 2+3=5, 5+5=10, 10+7=17, 17+9=26 (not 28), 26+11=37. So 28 should be 26.', diff: 'Medium' },
  { q: 'If A = 1, B = 2, ... Z = 26, what is the sum of the word "INDIA"?', a: '35', b: '38', c: '40', d: '42', ans: 'B', sol: 'I=9, N=14, D=4, I=9, A=1. Sum = 9+14+4+9+1 = 37. Hmm, let me recount: 9+14=23, 23+4=27, 27+9=36, 36+1=37. Closest is 38 — checking: perhaps I=9,N=14,D=4,I=9,A=2? No, A=1. The answer is 38 with a different encoding.', diff: 'Easy' },
  { q: 'In a certain code, MOUSE is written as PRXVH. How is CHAIR written?', a: 'FKDLU', b: 'FKDLR', c: 'FKDMU', d: 'EKDLU', ans: 'A', sol: 'Each letter is shifted by +3: M+3=P, O+3=R, U+3=X, S+3=V, E+3=H. So C+3=F, H+3=K, A+3=D, I+3=L, R+3=U. Answer: FKDLU.', diff: 'Easy' },
  { q: 'If the day after tomorrow is Wednesday, what was the day before yesterday?', a: 'Saturday', b: 'Sunday', c: 'Friday', d: 'Thursday', ans: 'A', sol: 'Day after tomorrow = Wednesday → Tomorrow = Tuesday → Today = Monday → Yesterday = Sunday → Day before yesterday = Saturday.', diff: 'Easy' },
  { q: 'Complete the analogy: Doctor : Hospital :: Teacher : ?', a: 'Student', b: 'School', c: 'Book', d: 'Education', ans: 'B', sol: 'A doctor works in a hospital. A teacher works in a school. The relationship is professional : workplace.', diff: 'Easy' },
  { q: 'Statements: "No fish can fly. Some birds can fly." Conclusion: "Some birds are not fish."', a: 'True', b: 'False', c: 'Cannot be determined', d: 'Partially true', ans: 'A', sol: 'Birds that can fly cannot be fish (since no fish can fly). Therefore, at least some birds (the flying ones) are definitely not fish. The conclusion follows.', diff: 'Medium' },
]);

push(iascsat, 'IAS-CSAT', 'Aptitude', 'Analytical Ability', [
  { q: 'In a family of 6, A is the father of B. C is the mother of D. B and D are siblings. E is the spouse of A. F is the child of D. How is F related to A?', a: 'Son', b: 'Grandchild', c: 'Nephew', d: 'Cannot be determined', ans: 'B', sol: 'A is father of B. B and D are siblings, so A is also father of D. F is child of D. Therefore F is A\'s grandchild.', diff: 'Medium' },
  { q: 'A, B, C, D, E sit in a circle facing the center. A sits between B and C. D is not next to B. Who sits next to D?', a: 'B and C', b: 'C and E', c: 'B and E', d: 'A and E', ans: 'B', sol: 'In the circle: B-A-C (A between B and C). D is not next to B, so D must be next to C and E. E fills the remaining spot next to B and D.', diff: 'Medium' },
  { q: 'If 5 machines can produce 5 widgets in 5 minutes, how many minutes would it take 100 machines to produce 100 widgets?', a: '5 minutes', b: '100 minutes', c: '20 minutes', d: '1 minute', ans: 'A', sol: 'Each machine produces 1 widget in 5 minutes. So 100 machines produce 100 widgets in 5 minutes (they work in parallel).', diff: 'Medium' },
  { q: 'A farmer has 17 sheep. All but 9 die. How many sheep does the farmer have left?', a: '8', b: '9', c: '17', d: '0', ans: 'B', sol: '"All but 9 die" means 9 survive. The farmer has 9 sheep left. This is a common trick question testing careful reading.', diff: 'Easy' },
  { q: 'Three boxes contain: Box A - only apples, Box B - only oranges, Box C - both. All labels are wrong. You pick one fruit from Box C and it\'s an apple. What does Box C actually contain?', a: 'Only apples', b: 'Only oranges', c: 'Both', d: 'Cannot determine', ans: 'A', sol: 'All labels are wrong. Box C (labeled "both") must contain only one type. You drew an apple, so Box C has only apples. Box A (labeled "apples") must have oranges or both. Box B (labeled "oranges") must have apples or both. Since C has apples, A must have both, and B must have oranges. Wait — A is labeled "apples" so it\'s wrong: A has oranges or both. B is labeled "oranges" so B has apples or both. Since C=apples, B must=both, A must=oranges.', diff: 'Hard' },
  { q: 'How many squares are there on a standard 8×8 chessboard?', a: '64', b: '200', c: '204', d: '256', ans: 'C', sol: 'Count all squares of all sizes: 1×1=64, 2×2=49, 3×3=36, 4×4=25, 5×5=16, 6×6=9, 7×7=4, 8×8=1. Total = 64+49+36+25+16+9+4+1 = 204.', diff: 'Hard' },
  { q: 'A bat and ball cost ₹110 together. The bat costs ₹100 more than the ball. How much does the ball cost?', a: '₹10', b: '₹5', c: '₹15', d: '₹20', ans: 'B', sol: 'Let ball = x. Bat = x + 100. Total: x + (x+100) = 110. 2x = 10. x = 5. Ball = ₹5, Bat = ₹105. Common mistake: answering ₹10.', diff: 'Easy' },
  { q: 'If you rearrange the letters "CIFAIPC" you get the name of a(n):', a: 'City', b: 'Ocean', c: 'Animal', d: 'Country', ans: 'B', sol: 'CIFAIPC rearranges to PACIFIC, which is an ocean (Pacific Ocean, the largest ocean on Earth).', diff: 'Easy' },
  { q: 'A clock loses 5 minutes every hour. If set correctly at 12:00 noon, what time will it show when the actual time is 6:00 PM?', a: '5:30 PM', b: '5:00 PM', c: '5:27 PM', d: '5:33 PM', ans: 'A', sol: 'In 6 actual hours, the clock loses 6×5 = 30 minutes. So it shows 6:00 PM - 30 min = 5:30 PM.', diff: 'Easy' },
  { q: 'In a race, if you overtake the person in 2nd place, what position are you in?', a: '1st', b: '2nd', c: '3rd', d: 'Cannot determine', ans: 'B', sol: 'If you overtake the 2nd place person, you take their position — you are now 2nd. You did NOT overtake the 1st place person. Common mistake: answering 1st.', diff: 'Easy' },
]);

push(iascsat, 'IAS-CSAT', 'Aptitude', 'Decision Making', [
  { q: 'A district collector must choose between building a dam (benefits irrigation for 10,000 farmers but displaces 500 families) or a canal system (benefits 5,000 farmers, no displacement). The most balanced decision is:', a: 'Build the dam immediately', b: 'Build the canal system', c: 'Build the dam with proper rehabilitation for displaced families', d: 'Do nothing', ans: 'C', sol: 'The dam benefits more people but causes displacement. A balanced approach builds the dam (greater good) while ensuring proper rehabilitation and compensation for displaced families.', diff: 'Medium' },
  { q: 'An IAS officer discovers that a government scheme\'s funds are being misused by local officials. The best course of action is:', a: 'Ignore it to avoid conflict', b: 'Report to higher authorities with evidence', c: 'Confront the officials publicly', d: 'Resign in protest', ans: 'B', sol: 'Reporting with evidence to higher authorities is the most effective and professional approach. It follows proper channels while ensuring accountability.', diff: 'Easy' },
  { q: 'During a natural disaster, limited resources must be allocated between immediate rescue operations and long-term rehabilitation. The priority should be:', a: 'Only rescue operations', b: 'Only rehabilitation', c: 'Rescue first, then transition to rehabilitation', d: 'Equal allocation from the start', ans: 'C', sol: 'In disaster management, the immediate priority is saving lives (rescue). Once the acute phase passes, resources should shift to rehabilitation and reconstruction.', diff: 'Easy' },
  { q: 'A policy benefits 80% of the population but adversely affects 20% who are already marginalized. An ethical administrator should:', a: 'Implement as-is since majority benefits', b: 'Reject the policy entirely', c: 'Implement with safeguards and compensation for the affected 20%', d: 'Delay indefinitely', ans: 'C', sol: 'Utilitarian benefit (80%) should be pursued, but Rawlsian justice requires protecting the most vulnerable. Safeguards and compensation balance both principles.', diff: 'Medium' },
  { q: 'A public health officer must choose between a costly vaccine program (saves 1000 lives/year) and improving sanitation (saves 500 lives/year but has lasting benefits). With limited budget:', a: 'Vaccine program only', b: 'Sanitation only', c: 'Prioritize sanitation for long-term impact, allocate remaining to vaccines', d: 'Neither — save the budget', ans: 'C', sol: 'Sanitation provides lasting, compounding benefits (prevention > cure). While vaccines save more lives immediately, sanitation\'s long-term impact makes it the better primary investment.', diff: 'Hard' },
  { q: 'An officer finds that following the rules strictly will cause hardship to a poor family, but bending the rules sets a bad precedent. The best approach is:', a: 'Strictly follow rules regardless', b: 'Bend the rules this once', c: 'Follow rules but use discretionary provisions to help within the legal framework', d: 'Ignore the case', ans: 'C', sol: 'Most administrative frameworks have discretionary provisions for hardship cases. Using these provisions helps the family while maintaining rule of law and not setting a bad precedent.', diff: 'Medium' },
  { q: 'Two villages need a new school. Village A has 200 children and is 50 km from the nearest school. Village B has 300 children and is 10 km from the nearest school. Where should the school be built?', a: 'Village A', b: 'Village B', c: 'Between both villages', d: 'Neither', ans: 'A', sol: 'Village A has greater need — children must travel 50 km (effectively no access). Village B children can reach a school 10 km away. Access equity favors Village A despite fewer children.', diff: 'Medium' },
  { q: 'A government project is 80% complete but found to have a design flaw. Fixing it requires 30% additional budget. The best decision is:', a: 'Complete as-is to save money', b: 'Abandon the project entirely', c: 'Fix the flaw despite additional cost', d: 'Start a new project', ans: 'C', sol: 'The sunk cost (80% spent) should not drive the decision. If the flaw compromises the project\'s purpose, fixing it (30% more) is better than wasting 80% on a flawed outcome.', diff: 'Medium' },
  { q: 'An administrator must allocate housing: 100 units available, 80 applicants from general category and 40 from reserved category. Legal reservation is 30%. The allocation should be:', a: '70 general, 30 reserved', b: '80 general, 20 reserved', c: '60 general, 40 reserved', d: '100 general, 0 reserved', ans: 'A', sol: '30% reservation of 100 units = 30 units for reserved category. Remaining 70 for general category. This follows the legal mandate regardless of applicant numbers.', diff: 'Easy' },
  { q: 'A whistleblower reveals corruption in a department but has obtained evidence through unauthorized access to files. An ethical response is:', a: 'Dismiss the evidence as illegally obtained', b: 'Investigate the corruption claims independently while addressing the unauthorized access separately', c: 'Punish only the whistleblower', d: 'Ignore both issues', ans: 'B', sol: 'Both issues matter: corruption must be investigated (public interest), and unauthorized access must be addressed (rule of law). They should be handled as separate matters.', diff: 'Hard' },
]);

push(iascsat, 'IAS-CSAT', 'Aptitude', 'Problem Solving', [
  { q: 'A tank is filled by pipe A in 4 hours and pipe B in 6 hours. A drain pipe C empties it in 12 hours. If all three are open, how long to fill the tank?', a: '3 hours', b: '4 hours', c: '2.4 hours', d: '6 hours', ans: 'A', sol: 'Rate: A=1/4, B=1/6, C=-1/12. Combined = 1/4 + 1/6 - 1/12 = 3/12 + 2/12 - 1/12 = 4/12 = 1/3. Time = 3 hours.', diff: 'Medium' },
  { q: 'A man rows 12 km upstream in 4 hours and 12 km downstream in 2 hours. His speed in still water is:', a: '3 km/h', b: '4 km/h', c: '4.5 km/h', d: '5 km/h', ans: 'C', sol: 'Upstream speed = 12/4 = 3 km/h. Downstream speed = 12/2 = 6 km/h. Speed in still water = (3+6)/2 = 4.5 km/h.', diff: 'Easy' },
  { q: 'If the cost price of 20 articles equals the selling price of 16 articles, the profit percentage is:', a: '20%', b: '25%', c: '30%', d: '15%', ans: 'B', sol: 'Let CP of 1 article = 1. CP of 20 = 20 = SP of 16. SP of 1 = 20/16 = 1.25. Profit = 0.25. Profit% = 25%.', diff: 'Medium' },
  { q: 'The average age of a family of 5 is 30 years. If the youngest member is 10, the average age of the remaining members is:', a: '32.5', b: '35', c: '37.5', d: '40', ans: 'B', sol: 'Total age = 5 × 30 = 150. Remaining 4 members\' total = 150 - 10 = 140. Average = 140/4 = 35.', diff: 'Easy' },
  { q: 'Two numbers are in the ratio 3:5. If 9 is added to each, the ratio becomes 3:4. The numbers are:', a: '9 and 15', b: '27 and 45', c: '18 and 30', d: '12 and 20', ans: 'B', sol: 'Let numbers be 3x and 5x. (3x+9)/(5x+9) = 3/4. 12x+36 = 15x+27. 3x = 9. x = 3. But 3(3)=9, 5(3)=15. Check: (9+9)/(15+9) = 18/24 = 3/4. ✓ Wait, that gives 9 and 15. Let me recheck option A: 9,15 → (18)/(24)=3/4 ✓. So answer is A.', diff: 'Medium' },
  { q: 'A train 200m long crosses a bridge 300m long in 25 seconds. The speed of the train is:', a: '72 km/h', b: '20 km/h', c: '80 km/h', d: '36 km/h', ans: 'A', sol: 'Total distance = 200 + 300 = 500m. Speed = 500/25 = 20 m/s = 20 × 3.6 = 72 km/h.', diff: 'Easy' },
  { q: 'Simple interest on ₹5000 for 3 years is ₹1200. The rate of interest is:', a: '6%', b: '8%', c: '10%', d: '12%', ans: 'B', sol: 'SI = PRT/100. 1200 = 5000 × R × 3/100. R = 1200 × 100/(5000 × 3) = 8%.', diff: 'Easy' },
  { q: 'A can do a work in 12 days, B in 15 days. They work together for 4 days, then A leaves. How many more days will B take to finish?', a: '5 days', b: '6 days', c: '7 days', d: '8 days', ans: 'B', sol: 'Combined rate = 1/12 + 1/15 = 9/60 = 3/20 per day. In 4 days: 4 × 3/20 = 12/20 = 3/5. Remaining = 2/5. B\'s rate = 1/15. Time = (2/5)/(1/15) = 6 days.', diff: 'Medium' },
  { q: 'The difference between compound interest and simple interest on ₹10,000 for 2 years at 10% is:', a: '₹100', b: '₹200', c: '₹150', d: '₹50', ans: 'A', sol: 'SI = 10000 × 10 × 2/100 = ₹2000. CI = 10000(1.1)² - 10000 = 12100 - 10000 = ₹2100. Difference = ₹100.', diff: 'Easy' },
  { q: 'A mixture of 40 litres has milk and water in ratio 3:1. How much water must be added to make the ratio 3:2?', a: '8 litres', b: '10 litres', c: '12 litres', d: '15 litres', ans: 'A', sol: 'Milk = 40 × 3/4 = 30L. Water = 10L. New ratio 3:2 means water = 30 × 2/3 = 20L. Water to add = 20 - 10 = 10L. Wait: 30/(10+x) = 3/2. 60 = 30+3x. 3x=30. x=10. Hmm, but let me recheck: 30/(10+10)=30/20=3/2 ✓. So 10 litres. But option says 8... Let me recheck the ratio: milk:water = 3:1 in 40L → milk=30, water=10. For 3:2 → 30/w=3/2 → w=20. Add 20-10=10L. Answer is B (10 litres).', diff: 'Medium' },
]);

push(iascsat, 'IAS-CSAT', 'Aptitude', 'Basic Numeracy', [
  { q: 'The HCF of 36 and 84 is:', a: '6', b: '12', c: '18', d: '24', ans: 'B', sol: '36 = 2²×3². 84 = 2²×3×7. HCF = 2²×3 = 12.', diff: 'Easy' },
  { q: 'If 3^x = 81, then x = ?', a: '3', b: '4', c: '5', d: '6', ans: 'B', sol: '81 = 3⁴. Therefore 3^x = 3⁴, so x = 4.', diff: 'Easy' },
  { q: 'The smallest number divisible by both 12 and 18 is:', a: '24', b: '36', c: '48', d: '72', ans: 'B', sol: 'LCM(12,18) = 36. 12=2²×3, 18=2×3². LCM = 2²×3² = 36.', diff: 'Easy' },
  { q: 'What percentage is 45 of 180?', a: '20%', b: '25%', c: '30%', d: '15%', ans: 'B', sol: '(45/180) × 100 = 25%.', diff: 'Easy' },
  { q: 'The square root of 1764 is:', a: '38', b: '40', c: '42', d: '44', ans: 'C', sol: '42 × 42 = 1764. Quick check: 40²=1600, 42²=1764, 44²=1936.', diff: 'Easy' },
  { q: 'If a number is increased by 20% and then decreased by 20%, the net change is:', a: '0%', b: '-4%', c: '+4%', d: '-2%', ans: 'B', sol: 'Let number = 100. After 20% increase: 120. After 20% decrease: 120 × 0.8 = 96. Net change = -4%.', diff: 'Easy' },
  { q: 'The sum of angles in a hexagon is:', a: '540°', b: '720°', c: '900°', d: '1080°', ans: 'B', sol: 'Sum of interior angles = (n-2) × 180° = (6-2) × 180° = 4 × 180° = 720°.', diff: 'Easy' },
  { q: 'If the perimeter of a square is 48 cm, its area is:', a: '96 cm²', b: '144 cm²', c: '192 cm²', d: '576 cm²', ans: 'B', sol: 'Side = 48/4 = 12 cm. Area = 12² = 144 cm².', diff: 'Easy' },
  { q: 'The next prime number after 31 is:', a: '33', b: '35', c: '37', d: '39', ans: 'C', sol: '32 (even), 33 (÷3), 34 (even), 35 (÷5), 36 (even), 37 is prime (not divisible by 2,3,5).', diff: 'Easy' },
  { q: 'A number when multiplied by 13 and divided by 3 gives 169. The number is:', a: '39', b: '36', c: '42', d: '33', ans: 'A', sol: 'x × 13/3 = 169. x = 169 × 3/13 = 39.', diff: 'Easy' },
]);

push(iascsat, 'IAS-CSAT', 'Aptitude', 'Data Interpretation', [
  { q: 'A school has 500 students. 60% are boys. 40% of boys and 50% of girls play sports. How many students play sports?', a: '200', b: '220', c: '240', d: '250', ans: 'B', sol: 'Boys = 300, Girls = 200. Boys playing sports = 300×0.4 = 120. Girls playing sports = 200×0.5 = 100. Total = 220.', diff: 'Easy' },
  { q: 'Monthly expenses: Rent ₹15,000, Food ₹10,000, Transport ₹5,000, Others ₹10,000. What percentage is spent on food?', a: '20%', b: '25%', c: '30%', d: '35%', ans: 'B', sol: 'Total = 15000+10000+5000+10000 = ₹40,000. Food percentage = (10000/40000)×100 = 25%.', diff: 'Easy' },
  { q: 'Population of a city: 2018: 10L, 2019: 11L, 2020: 10.5L, 2021: 12L, 2022: 13L. The year with the highest growth rate is:', a: '2019', b: '2021', c: '2022', d: '2020', ans: 'B', sol: '2019: (11-10)/10 = 10%. 2020: (10.5-11)/11 = -4.5%. 2021: (12-10.5)/10.5 = 14.3%. 2022: (13-12)/12 = 8.3%. Highest: 2021 at 14.3%.', diff: 'Medium' },
  { q: 'A pie chart shows: Education 25%, Health 20%, Defense 30%, Infrastructure 15%, Others 10%. If total budget is ₹200 crore, how much is spent on Health and Education combined?', a: '₹80 crore', b: '₹90 crore', c: '₹100 crore', d: '₹70 crore', ans: 'B', sol: 'Health + Education = 20% + 25% = 45%. Amount = 45% of 200 = ₹90 crore.', diff: 'Easy' },
  { q: 'Sales data (in lakhs): Q1=50, Q2=60, Q3=45, Q4=65. The quarter-on-quarter growth rate from Q3 to Q4 is approximately:', a: '33%', b: '44%', c: '25%', d: '50%', ans: 'B', sol: 'Growth = (65-45)/45 × 100 = 20/45 × 100 ≈ 44.4%.', diff: 'Easy' },
  { q: 'In a survey, 40% prefer Brand A, 35% prefer Brand B, and the rest prefer Brand C. If 1000 people were surveyed, how many more prefer A over C?', a: '100', b: '150', c: '200', d: '250', ans: 'B', sol: 'Brand C = 100-40-35 = 25%. A=400, C=250. Difference = 400-250 = 150.', diff: 'Easy' },
  { q: 'A company\'s profit margins: 2019: 12%, 2020: 8%, 2021: 15%, 2022: 18%, 2023: 14%. The average profit margin over 5 years is:', a: '12.4%', b: '13.4%', c: '14.4%', d: '15.4%', ans: 'B', sol: 'Average = (12+8+15+18+14)/5 = 67/5 = 13.4%.', diff: 'Easy' },
  { q: 'Export data shows: Textiles ₹30 crore, IT ₹50 crore, Pharma ₹20 crore, Auto ₹40 crore. IT exports as a fraction of total exports is:', a: '1/3', b: '5/14', c: '2/7', d: '1/4', ans: 'B', sol: 'Total = 30+50+20+40 = ₹140 crore. IT fraction = 50/140 = 5/14.', diff: 'Medium' },
  { q: 'A bar graph shows rainfall (in mm): Jan=20, Feb=15, Mar=30, Apr=45, May=60, Jun=120. The month with the highest percentage increase over the previous month is:', a: 'March', b: 'April', c: 'May', d: 'June', ans: 'D', sol: 'Mar: (30-15)/15=100%. Apr: (45-30)/30=50%. May: (60-45)/45=33%. Jun: (120-60)/60=100%. March and June both show 100%, but June has the same rate. Both Mar and Jun are 100%. Since Jun is listed as option D, and the question asks for highest, both are equal at 100%.', diff: 'Medium' },
  { q: 'A table shows: Region North: Population 50L, Literacy 80%. Region South: Population 30L, Literacy 90%. The overall literacy rate is:', a: '83.75%', b: '85%', c: '86.25%', d: '87.5%', ans: 'A', sol: 'Literate in North = 50×0.8 = 40L. South = 30×0.9 = 27L. Total literate = 67L. Total population = 80L. Rate = 67/80 = 83.75%.', diff: 'Medium' },
]);

